import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
groups=[]
def workshop(title,sources):
    rows=[];groups.append((title,sources,rows));return rows
def C(rows,title,brief,options,answer,why,code=''):
    rows.append(dict(type='choice',title=title,brief=brief,options=options,solution=answer,explanation=why,code=code))
def I(rows,title,code,answer,why):
    rows.append(dict(type='input',title=title,brief='Escribe la salida exacta, sin comillas ni texto adicional.',options=[],solution=answer,explanation=why,code=code))
def B(rows,title,code,options,answer,why):
    rows.append(dict(type='blank',title=title,brief='Arrastra al hueco la pieza que completa el código.',options=options,solution=answer,explanation=why,code=code))
def O(rows,title,lines,why):
    rows.append(dict(type='order',title=title,brief='Ordena las líneas para obtener un programa válido. Conserva la sangría.',options=lines,solution=list(range(len(lines))),explanation=why,code=''))
def V(rows,title,statement,truth,why):
    rows.append(dict(type='boolean',title=title,brief=statement,options=['Verdadero','Falso'],solution=0 if truth else 1,explanation=why,code=''))

