quizzes=[]
for s,(topic,sources,rows) in enumerate(groups,1):
    assert len(rows)==20,(topic,len(rows))
    for j,mode in enumerate(['practica','vivo']):
        qs=[]
        for i,q in enumerate(rows[j*10:(j+1)*10],1):
            q={**q,'id':i,'topic':topic,'points':2}
            # Distribuir las alternativas correctas entre distintas posiciones.
            if q['type'] in ('choice','blank'):
                offset=(s+i+j)%4
                q['options']=q['options'][offset:]+q['options'][:offset]
                q['solution']=(q['solution']-offset)%4
            qs.append(q)
        quizzes.append(dict(id=f'sc26-s{s}-{mode}',title=f'Taller {s} · {topic} · {"Práctica" if j==0 else "En vivo"}',description=f'{"Entrena a tu ritmo" if j==0 else "Comparte el reto con tu grupo"}: diez preguntas originales del taller {s}. Basado en: {", ".join(sources)}.',course=f'Structural Coders · Taller {s}',cycle='2026-1',code=f'S{s}{"PRAC" if j==0 else "VIVO"}',hints=True,practice=True,game=dict(enabled=j==0,timer=0,speed=False,powerups=True,leaderboard=True),questions=qs,updatedAt='2026-10-18T12:00:00.000Z'))
assert len({q['title'] for quiz in quizzes for q in quiz['questions']})==140
out=ROOT/'content';out.mkdir(exist_ok=True)
(out/'workshops.json').write_text(json.dumps(dict(format='structural-coders-quiz',version=1,quizzes=quizzes),ensure_ascii=False,indent=2),encoding='utf-8')
print('14 cuestionarios, 140 preguntas únicas, 5 dinámicas. Banco generado.')
